import os
import json

import httpx

api_key = os.getenv("DASHSCOPE_API_KEY")
base_url = "https://dashscope.aliyuncs.com/compatible-mode/v1"

request_body = {
    "model": "qwen3-omni-flash",
    "messages": [
        {
            "role": "user",
            "content": [
                {
                    "type": "input_audio",
                    "input_audio": {
                        "data": "https://help-static-aliyun-doc.aliyuncs.com/file-manage-files/zh-CN/20250211/tixcef/cherry.wav",
                        "format": "wav",
                    },
                },
                {"type": "text", "text": "这段音频在说什么"},
            ],
        },
    ],
    "modalities": ["text"],
    "stream": True,
    "stream_options": {"include_usage": True},
}

headers = {
    "Authorization": f"Bearer {api_key}",
    "Content-Type": "application/json",
}

request_body = [{"role": "system", "content": "你是一个专业的语音识别助手。你的任务是：\n\n1. 接收用户上传的音频文件\n2. 将音频内容准确转换为文本\n3. 处理各种音频质量和环境噪音\n4. 识别专业术语和特殊词汇\n5. 保持转录的准确性和完整性\n\n请始终提供清晰、准确的转录结果。如果音频质量较差或有不清楚的部分，请在相应位置标注 [不清楚] 或 [噪音]。"}, {"role": "user", "content": [{"type": "text", "text": "User input: "}, {"type": "input_audio", "input_audio": {"format": "wav", "data": "data:;base64,"}}]}]

with httpx.stream(
        "POST",
        f"{base_url}/chat/completions",
        headers=headers,
        json=request_body,
        timeout=60.0,
) as response:
    for line in response.iter_lines():
        if line.startswith("data: "):
            data_str = line[6:]  # Remove "data: " prefix
            if data_str == "[DONE]":
                break
            try:
                data = json.loads(data_str)
                print(data["choices"][0]["delta"]["content"], end="")
            except json.JSONDecodeError:
                print(f"Failed to decode: {data_str}")
